sys_script_client.script:
function onLoad() { //MSSTRUSTES-83
    g_form.setSectionDisplay('comments', false);

    var allFields = ['number', 'state', 'stage', 'assigned_to', 'assignment_group', 'return_case_aml', 'aml_kyc_case','has_breached'];

    allFields.forEach(function(field) { //make all fields readonly.
        g_form.setReadOnly(field, true);
    });


	var stageValue = g_form.getValue('stage');  //MSSTRUSTES-317
    if (stageValue !== '400' && stageValue !== '500') {
        g_form.setReadOnly('stage', false);
			g_form.removeOption('stage', '400');
    g_form.removeOption('stage', '500');
    }
	else{
		g_form.setReadOnly('stage', true);
	}
    // If ops_admin, make assigned_to editable //MSSTRUSTES-253.
    if (g_user.hasRole('x_hsb11_mss_trus_0.ops_admin')) {
        g_form.setReadOnly('assigned_to', false);
    }
}
